import json
import numpy as np

# Fix np.float64 serialization
with open('/app/output/metrics.json', 'r') as f:
    metrics = json.load(f)

# Convert any remaining np types
class NpEncoder(json.JSONEncoder):
    def default(self, obj):
        if isinstance(obj, np.integer):
            return int(obj)
        if isinstance(obj, np.floating):
            return float(obj)
        if isinstance(obj, np.ndarray):
            return obj.tolist()
        return super(NpEncoder, self).default(obj)

with open('/app/output/metrics.json', 'w') as f:
    json.dump(metrics, f, indent=2, cls=NpEncoder)

print("Fixed metrics JSON")
